 const client:ConnectedProjectionClient<Mighty>={room,game:{version:31,room_version:31,turn:'Over',grace_ms:0,legal:[],out_of_turn:[],notes:{unplayable:[],contracts:[]},view},seat:null,viewerId:'observer',viewerName:'Observer',roomScope:{...saved.scope!,actor_id:'observer',seat:null,hand:3,version:31}};const rawDocument=mightyDocument(client,31)!;const outcome=projectMightyOutcome({client,document:rawDocument,roomScope:client.roomScope!});expect(outcome).not.toBeNull();const document={...rawDocument,outcome:outcome!.outcome,information:[...(rawDocument.information??[]),outcome!.information],collections:outcome!.collections??rawDocument.collections};expect(document).not.toBeNull();const done=view.phase.Done,plays=done.tricks[0].plays;
 const beforeDocument=mightyDocument({room:{...room,in_hand:true,hands_played:2,current_hand:null},game:{version:30,room_version:30,turn:{Seat:4},grace_ms:0,legal:[],out_of_turn:[],notes:{unplayable:[],contracts:[]},view:{...view,hand_sizes:[0,0,0,0,1],phase:{Play:{declarer:done.declarer,friend:done.friend,contract:done.contract,call:done.call,no_friend:false,trick_no:9,leader:0,lead:done.tricks[0].lead,plays:plays.slice(0,4),leading:3,called_joker:null,tricks:[],discards:null}}}},seat:null,viewerId:'observer',viewerName:'Observer',roomScope:{...saved.scope!,actor_id:'observer',seat:null,hand:3,version:30}},30);expect(beforeDocument).not.toBeNull();
 const session=createCardSession({transport:()=>{}});session.receive(beforeDocument!);
 const metric={fontSize:15,lineHeight:18,fontWeight:600,paddingX:16,paddingY:10,minHeight:44,pulse:1},environment={width:1280,height:800,fontFamily:'sans-serif',fontRevision:'one',textScale:1,revision:'one',controls:{command:metric,choice:metric}},table=createCardTable({session});let published:PresentationFrame|null=null;
 table.attach({identity:{},environment:()=>environment,listen:()=>()=>{},measure(requests,reply){reply(requests.map(request=>{const natural=Array.from(request.text).length*8,width=request.width===null?natural:Math.min(natural,request.width),height=typography(request.role,environment).lineHeight*Math.max(1,Math.ceil(natural/Math.max(1,width)));return {key:request.key,size:{width,height}};}));return()=>{};},publish(value){published=value;},disarm:()=>{},invalidate:()=>{},clear:()=>{},fallback:()=>{}});
 if(published===null){const state=table.inspect();console.info('counted-runtime-initial-publication',{status:state.status,pending:state.pending,cacheSize:state.cacheSize,candidateGeneration:state.candidateGeneration});}
 const previous=(published as PresentationFrame|null)!;expect(previous).not.toBeNull();expect(previous.nodes.filter(node=>node.kind==='card'&&node.collectionPurpose==='play')).toHaveLength(4);
 session.receive(document!);
 const owned=(published as PresentationFrame|null)!;expect(owned).not.toBeNull();expect(owned).not.toBe(previous);expect(Object.isFrozen(owned)).toBe(true);
 const {resourceMotionIndex}=await import('./resourceMotionIndex'),{planTrickResolution}=await import('./trickResolution');
 const resources=resourceMotionIndex(owned);expect(resources).not.toBeNull();const captured=resources!.collections.filter(collection=>collection.purpose==='captured');expect(captured).toHaveLength(1);expect(captured[0].cards).toHaveLength(5);expect(captured[0].cards.map(card=>card.entityId)).toEqual(plays.map(play=>JSON.stringify(play.card)));expect(new Set(captured[0].cards.map(card=>card.ownerId))).toEqual(new Set(record.participant_ids));
 expect(owned.nodes.filter(node=>node.collectionPurpose==='captured')).toEqual([]);expect(owned.nodes.filter(node=>node.entityId&&captured[0].cards.some(card=>card.entityId===node.entityId))).toEqual([]);
 const plan=planTrickResolution(previous,owned);expect(plan).not.toBeNull();expect(plan!.cards).toEqual(captured[0].cards);expect(plan!.items).toHaveLength(5);expect(plan!.items.every(item=>item.destinationId===undefined&&owned.nodes.some(node=>node.id===item.slotId&&node.trickSlot&&node.ownerId===item.ownerId))).toBe(true);expect(plan!.incomingId).toBe(JSON.stringify(plays[4].card));expect(owned.publicCompletion).toBeDefined();
